import{_ as a,o as t,c as i,ae as o}from"./chunks/framework.Dh1jimFm.js";const c=JSON.parse('{"title":"Common Issues","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/common-issues.md","filePath":"troubleshooting/common-issues.md"}'),s={name:"troubleshooting/common-issues.md"};function r(l,e,n,h,d,p){return t(),i("div",null,e[0]||(e[0]=[o(`<h1 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h1><p>Solutions to frequently encountered problems.</p><h2 id="startup-issues" tabindex="-1">Startup Issues <a class="header-anchor" href="#startup-issues" aria-label="Permalink to &quot;Startup Issues&quot;">​</a></h2><h3 id="application-won-t-start" tabindex="-1">Application won&#39;t start <a class="header-anchor" href="#application-won-t-start" aria-label="Permalink to &quot;Application won&#39;t start&quot;">​</a></h3><p><strong>Symptoms:</strong> Double-click does nothing, or window briefly appears then closes.</p><p><strong>Solutions:</strong></p><ol><li><p><strong>Run from command line</strong> to see error messages:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Supervertaler.py</span></span></code></pre></div></li><li><p><strong>Reset UI preferences</strong> (corrupted window state):</p><ul><li>Delete <code>user_data/ui_preferences.json</code></li><li>Restart the application</li></ul></li><li><p><strong>Check dependencies</strong>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements.txt</span></span></code></pre></div></li><li><p><strong>Verify Python version</strong> (needs 3.10+):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div></li></ol><h3 id="module-not-found-error" tabindex="-1">&quot;Module not found&quot; error <a class="header-anchor" href="#module-not-found-error" aria-label="Permalink to &quot;&quot;Module not found&quot; error&quot;">​</a></h3><p>Install the missing module:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">module-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Or reinstall all dependencies:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements.txt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-reinstall</span></span></code></pre></div><hr><h2 id="import-problems" tabindex="-1">Import Problems <a class="header-anchor" href="#import-problems" aria-label="Permalink to &quot;Import Problems&quot;">​</a></h2><h3 id="cannot-read-file-error" tabindex="-1">&quot;Cannot read file&quot; error <a class="header-anchor" href="#cannot-read-file-error" aria-label="Permalink to &quot;&quot;Cannot read file&quot; error&quot;">​</a></h3><ul><li>Close the file in other programs (Word, Excel, etc.)</li><li>Check if the file is read-only</li><li>Try copying the file to a different location</li></ul><h3 id="memoq-bilingual-shows-no-segments" tabindex="-1">memoQ bilingual shows no segments <a class="header-anchor" href="#memoq-bilingual-shows-no-segments" aria-label="Permalink to &quot;memoQ bilingual shows no segments&quot;">​</a></h3><ul><li>Ensure you exported as <strong>Bilingual DOCX</strong> (table format)</li><li>Check the file in Word to verify it has a source/target table</li></ul><h3 id="trados-package-fails-to-extract" tabindex="-1">Trados package fails to extract <a class="header-anchor" href="#trados-package-fails-to-extract" aria-label="Permalink to &quot;Trados package fails to extract&quot;">​</a></h3><ul><li>The SDLPPX might be corrupted</li><li>Re-export from Trados Studio</li><li>Check if the package includes all required files</li></ul><h3 id="encoding-errors-garbled-text" tabindex="-1">Encoding errors (garbled text) <a class="header-anchor" href="#encoding-errors-garbled-text" aria-label="Permalink to &quot;Encoding errors (garbled text)&quot;">​</a></h3><ul><li>Try opening the source file in Notepad++ to check encoding</li><li>Use <strong>Tools → Encoding Repair</strong> to fix common issues</li><li>Export from source tool with UTF-8 encoding</li></ul><hr><h2 id="translation-issues" tabindex="-1">Translation Issues <a class="header-anchor" href="#translation-issues" aria-label="Permalink to &quot;Translation Issues&quot;">​</a></h2><h3 id="ai-translation-returns-empty" tabindex="-1">AI translation returns empty <a class="header-anchor" href="#ai-translation-returns-empty" aria-label="Permalink to &quot;AI translation returns empty&quot;">​</a></h3><ol><li>Check your API key is valid</li><li>Verify you have credits with the provider</li><li>Check internet connection</li><li>Try a different model</li></ol><h3 id="rate-limit-exceeded-error" tabindex="-1">&quot;Rate limit exceeded&quot; error <a class="header-anchor" href="#rate-limit-exceeded-error" aria-label="Permalink to &quot;&quot;Rate limit exceeded&quot; error&quot;">​</a></h3><ul><li>Wait 1-2 minutes and try again</li><li>Reduce batch size</li><li>Upgrade your API plan</li></ul><h3 id="wrong-translation-language" tabindex="-1">Wrong translation language <a class="header-anchor" href="#wrong-translation-language" aria-label="Permalink to &quot;Wrong translation language&quot;">​</a></h3><ul><li>Check your prompt specifies the correct language pair</li><li>Verify source/target languages are set correctly in project settings</li></ul><h3 id="tags-are-removed-or-moved" tabindex="-1">Tags are removed or moved <a class="header-anchor" href="#tags-are-removed-or-moved" aria-label="Permalink to &quot;Tags are removed or moved&quot;">​</a></h3><p>Add explicit instructions to your prompt:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Keep all formatting tags like {1}, &lt;b&gt;, &lt;/b&gt; in exactly </span></span>
<span class="line"><span>the same positions in the translation.</span></span></code></pre></div><hr><h2 id="reimporting-issues" tabindex="-1">Reimporting Issues <a class="header-anchor" href="#reimporting-issues" aria-label="Permalink to &quot;Reimporting Issues&quot;">​</a></h2><h3 id="segments-don-t-match-on-reimport" tabindex="-1">Segments don&#39;t match on reimport <a class="header-anchor" href="#segments-don-t-match-on-reimport" aria-label="Permalink to &quot;Segments don&#39;t match on reimport&quot;">​</a></h3><p><strong>Cause:</strong> Segment structure changed.</p><p><strong>Solution:</strong></p><ul><li>Don’t merge or split segments in Supervertaler.</li><li>Export the matching format for your CAT tool/workflow.</li><li>If you’re working from a bilingual table, don’t modify the table structure in Word.</li></ul><h3 id="formatting-lost-on-reimport" tabindex="-1">Formatting lost on reimport <a class="header-anchor" href="#formatting-lost-on-reimport" aria-label="Permalink to &quot;Formatting lost on reimport&quot;">​</a></h3><p><strong>Cause:</strong> Tags/placeholders weren’t preserved.</p><p><strong>Solution:</strong></p><ul><li>Verify tags in Tag view before exporting.</li><li>Ensure tags are balanced and not renumbered.</li><li>Run CAT tool QA after import to catch tag issues early.</li></ul><h3 id="tm-matches-not-appearing" tabindex="-1">TM matches not appearing <a class="header-anchor" href="#tm-matches-not-appearing" aria-label="Permalink to &quot;TM matches not appearing&quot;">​</a></h3><p><strong>Cause:</strong> TM not loaded, disabled, or language mismatch.</p><p><strong>Solution:</strong></p><ul><li>Open <strong>Project resources → Translation Memories</strong>.</li><li>Ensure the TM is added and <strong>Read</strong> is enabled.</li><li>Verify source/target language pair matches your project.</li></ul><hr><h2 id="export-problems" tabindex="-1">Export Problems <a class="header-anchor" href="#export-problems" aria-label="Permalink to &quot;Export Problems&quot;">​</a></h2><h3 id="exported-docx-has-no-translations" tabindex="-1">Exported DOCX has no translations <a class="header-anchor" href="#exported-docx-has-no-translations" aria-label="Permalink to &quot;Exported DOCX has no translations&quot;">​</a></h3><ul><li>Make sure you translated the segments (target column isn&#39;t empty)</li><li>Check you&#39;re exporting the correct format</li><li>Verify the segments are confirmed</li></ul><h3 id="trados-sdlrpx-shows-draft-status" tabindex="-1">Trados SDLRPX shows &quot;Draft&quot; status <a class="header-anchor" href="#trados-sdlrpx-shows-draft-status" aria-label="Permalink to &quot;Trados SDLRPX shows &quot;Draft&quot; status&quot;">​</a></h3><p>Update to v1.9.32 or later - this bug was fixed.</p><h3 id="source-file-not-found-on-export" tabindex="-1">&quot;Source file not found&quot; on export <a class="header-anchor" href="#source-file-not-found-on-export" aria-label="Permalink to &quot;&quot;Source file not found&quot; on export&quot;">​</a></h3><p>The original imported file was moved or deleted.</p><ul><li>Use <strong>File → Relocate Source Folder</strong> to point to the new location</li><li>Or re-import the source file</li></ul><h3 id="formatting-lost-after-round-trip" tabindex="-1">Formatting lost after round-trip <a class="header-anchor" href="#formatting-lost-after-round-trip" aria-label="Permalink to &quot;Formatting lost after round-trip&quot;">​</a></h3><ul><li>Keep all inline tags in your translations</li><li>Don&#39;t modify the structure of bilingual tables</li><li>Check CAT tool import settings</li></ul><hr><h2 id="performance-issues" tabindex="-1">Performance Issues <a class="header-anchor" href="#performance-issues" aria-label="Permalink to &quot;Performance Issues&quot;">​</a></h2><h3 id="application-is-slow" tabindex="-1">Application is slow <a class="header-anchor" href="#application-is-slow" aria-label="Permalink to &quot;Application is slow&quot;">​</a></h3><ol><li><strong>Reduce segments per page</strong> in pagination settings (try 50)</li><li><strong>Disable spellcheck</strong> if not needed (Settings → View)</li><li><strong>Close other heavy applications</strong></li><li><strong>Disable Supermemory</strong> if not using it</li></ol><h3 id="navigation-between-segments-is-slow" tabindex="-1">Navigation between segments is slow <a class="header-anchor" href="#navigation-between-segments-is-slow" aria-label="Permalink to &quot;Navigation between segments is slow&quot;">​</a></h3><p>Fixed in v1.9.66:</p><ul><li>Termbase cache now works correctly</li><li>Verbose logging removed</li></ul><p>Update to the latest version.</p><h3 id="large-files-take-forever-to-import" tabindex="-1">Large files take forever to import <a class="header-anchor" href="#large-files-take-forever-to-import" aria-label="Permalink to &quot;Large files take forever to import&quot;">​</a></h3><ul><li>Very large files (10,000+ segments) may take time</li><li>Consider splitting into smaller files</li><li>Use multi-file import for better organization</li></ul><hr><h2 id="spellcheck-issues" tabindex="-1">Spellcheck Issues <a class="header-anchor" href="#spellcheck-issues" aria-label="Permalink to &quot;Spellcheck Issues&quot;">​</a></h2><h3 id="spellcheck-not-working" tabindex="-1">Spellcheck not working <a class="header-anchor" href="#spellcheck-not-working" aria-label="Permalink to &quot;Spellcheck not working&quot;">​</a></h3><ol><li>Check spellcheck is enabled: <strong>Settings → View Settings → Spellcheck</strong></li><li>Verify the correct language is selected</li><li>For Hunspell, ensure dictionaries are installed</li></ol><h3 id="wrong-language-being-checked" tabindex="-1">Wrong language being checked <a class="header-anchor" href="#wrong-language-being-checked" aria-label="Permalink to &quot;Wrong language being checked&quot;">​</a></h3><p>Go to <strong>Settings → View Settings → Spellcheck</strong> and select the correct target language.</p><h3 id="red-underlines-appear-everywhere" tabindex="-1">Red underlines appear everywhere <a class="header-anchor" href="#red-underlines-appear-everywhere" aria-label="Permalink to &quot;Red underlines appear everywhere&quot;">​</a></h3><p>The spellcheck language might not match your target language. Or you might need to add technical terms to your dictionary.</p><hr><h2 id="ui-issues" tabindex="-1">UI Issues <a class="header-anchor" href="#ui-issues" aria-label="Permalink to &quot;UI Issues&quot;">​</a></h2><h3 id="dark-mode-colors-look-wrong" tabindex="-1">Dark mode colors look wrong <a class="header-anchor" href="#dark-mode-colors-look-wrong" aria-label="Permalink to &quot;Dark mode colors look wrong&quot;">​</a></h3><p>Some widgets apply styles when becoming visible. Try:</p><ul><li>Switch themes back and forth</li><li>Restart the application</li></ul><h3 id="window-opens-off-screen" tabindex="-1">Window opens off-screen <a class="header-anchor" href="#window-opens-off-screen" aria-label="Permalink to &quot;Window opens off-screen&quot;">​</a></h3><p>Delete <code>user_data/ui_preferences.json</code> to reset window position.</p><h3 id="fonts-look-different-wrong" tabindex="-1">Fonts look different/wrong <a class="header-anchor" href="#fonts-look-different-wrong" aria-label="Permalink to &quot;Fonts look different/wrong&quot;">​</a></h3><p>Go to <strong>Settings → View Settings</strong> and select your preferred font family.</p><hr><h2 id="still-having-issues" tabindex="-1">Still Having Issues? <a class="header-anchor" href="#still-having-issues" aria-label="Permalink to &quot;Still Having Issues?&quot;">​</a></h2><ol><li>Check the <a href="https://github.com/michaelbeijer/Supervertaler/issues" target="_blank" rel="noreferrer">GitHub Issues</a> for known bugs</li><li>Open a new issue with: <ul><li>Your OS and Python version</li><li>Steps to reproduce the problem</li><li>Error messages (if any)</li><li>Screenshots (if helpful)</li></ul></li></ol>`,88)]))}const g=a(s,[["render",r]]);export{c as __pageData,g as default};
